"use client";
import {useEffect,useMemo,useRef,useState} from "react";
import {ArrowRight,ArrowLeft,BookOpen,BrainCircuit,Calculator,CalendarCheck,Check,CheckCircle2,ChevronDown,ChevronRight,ClipboardList,CreditCard,DollarSign,Download,Home,Info,LayoutDashboard,LockKeyhole,Menu,MessageCircle,Plus,RefreshCcw,Send,Settings,ShieldCheck,SlidersHorizontal,Sparkles,Target,TrendingUp,Wallet,X,AlertCircle,LogOut,Trash2,PanelTop,Eye,ShieldAlert} from "lucide-react";
import {browserSupabase} from "@/lib/supabase/client";
import {freeDiagnose,riskFromAnswers,simulateFuture, type Allocation} from "@/lib/engine";
import cards from "@/content/cards.json";

const money=(v:number)=>`${Math.round(v||0).toLocaleString("ko-KR")}만 원`;
const disclosure="본 서비스는 자산 종류의 일반적인 특성과 계산 예시를 제공하며, 개별 금융상품 추천이나 투자 권유를 하지 않습니다. 수익률은 가정이며 원금·수익을 보장하지 않습니다.";
const riskQuestions=[
  {q:"이 돈을 얼마나 안 쓰고 둘 수 있나요?",choices:["1년 미만","1~3년","3~5년","5년 이상"]},
  {q:"투자해 본 적이 있나요?",choices:["예적금만","펀드·ETF 조금","주식 직접 1년 이상","주식·코인 3년 이상"]},
  {q:"100만 원이 1년 뒤 80만 원이 되면?",choices:["바로 팔아요","조금 더 지켜봐요","회복을 기다려요","더 사요"]},
  {q:"월 소득이 얼마나 꼬박꼬박 들어오나요?",choices:["불규칙해요","조금 변동해요","대체로 일정해요","매우 안정적이에요"]},
  {q:"투자에서 바라는 것은?",choices:["원금 지키기","예금보다 조금 더","시장 평균 수익","시장보다 큰 수익"]}
];
type Stage="landing"|"login"|"signup"|"reset"|"finance"|"risk"|"goal"|"preview"|"app";
type Tab="home"|"blueprint"|"coach"|"future"|"settings";
type State={profile:any;risk:any;goal:any;assets:{kind:string;amount:number}[];blueprint:any;checkins:any[];points:number;messages:any[];proposals:any[]};
const emptyState:State={profile:null,risk:null,goal:null,assets:[],blueprint:null,checkins:[],points:0,messages:[],proposals:[]};
const defaultFin={nickname:"",income:280,income_type:"employee",fixed_expense:95,living_expense:70,debt_payment:0,analytics_consent:false};
const defaultAssets={deposit:800,domestic:0,overseas:0,etf:0,coin:0,other:0};
const assetKinds:[keyof typeof defaultAssets,string][]=[["deposit","예적금"],["domestic","국내 주식"],["overseas","해외 주식"],["etf","ETF"],["coin","가상자산"],["other","기타"]];
const icons={home:Home,blueprint:ClipboardList,coach:MessageCircle,future:TrendingUp,settings:Settings};
const tabLabels={home:"홈",blueprint:"설계도",coach:"AI 질문",future:"미래 자산",settings:"설정"};
const field=(v:unknown)=>typeof v==="number"&&Number.isFinite(v)?v:0;
const pct=(num:number,den:number)=>den>0?Math.round(num/den*100):0;
async function api(path:string,method="GET",payload?:unknown){
  const res=await fetch(`/api/${path}`,{method,headers:payload===undefined?undefined:{"Content-Type":"application/json"},body:payload===undefined?undefined:JSON.stringify(payload),cache:"no-store"});
  const data=await res.json().catch(()=>({error:"응답 형식 오류"}));
  if(!res.ok)throw Error(data.error||`요청 실패: ${res.status}`);
  return data;
}
function Brand({small=false}:{small?:boolean}){return <span className="brand"><span className="brand-logo"><TrendingUp size={small?19:23} strokeWidth={2.8}/></span><span>모아<span className="brand-accent">플랜</span></span>{!small&&<span className="brand-beta">BETA</span>}</span>;}
function Btn({children,onClick,outline=false,ghost=false,disabled=false,className="",type="button"}:{children:React.ReactNode;onClick?:()=>void;outline?:boolean;ghost?:boolean;disabled?:boolean;className?:string;type?:"button"|"submit"}){return <button type={type} disabled={disabled} onClick={onClick} className={`btn ${outline?"btn-outline":ghost?"btn-ghost":"btn-main"} ${className}`}>{children}</button>;}
function Block({children,className=""}:{children:React.ReactNode;className?:string}){return <section className={`card ${className}`}>{children}</section>;}
function Cap({children}:{children:React.ReactNode}){return <p className="muted caption">{children}</p>;}
function StepHead({eyebrow,title,subtitle,progress}:{eyebrow:string;title:string;subtitle?:string;progress?:number}){return <div className="section-head"><span className="eyebrow">{eyebrow}</span><h1>{title}</h1>{subtitle&&<p className="muted">{subtitle}</p>}{progress!==undefined&&<div className="progress-rail"><div style={{width:`${progress}%`}}/></div>}</div>;}
function Num({label,value,onChange,hint,min=0,max=10000000}:{label:string;value:number;onChange:(n:number)=>void;hint?:string;min?:number;max?:number}){return <label className="field-wrap"><span className="field-label">{label}</span><div className="numeric"><input type="number" min={min} max={max} step="1" inputMode="numeric" value={value} onChange={e=>onChange(Math.max(min,Math.min(max,Math.floor(Number(e.target.value)||0))))}/><span>만원</span></div>{hint&&<span className="field-hint">{hint}</span>}</label>;}
function Toast({message,onDismiss}:{message:string;onDismiss:()=>void}){return message?<div className="toast"><AlertCircle size={18}/><span>{message}</span><button onClick={onDismiss} aria-label="닫기"><X size={18}/></button></div>:null;}
function Ring({value,label,sub}:{value:number;label:string;sub?:string}){const v=Math.min(100,Math.max(0,value));return <div className="ring" style={{background:`conic-gradient(#4466f5 0 ${v}%,#e8edf5 ${v}% 100%)`}}><div className="ring-core"><b>{value}%</b><small>{label}</small>{sub&&<small>{sub}</small>}</div></div>;}
function Bar({entries}:{entries:{label:string;value:number;color:string}[]}){const sum=entries.reduce((s,x)=>s+x.value,0);return <><div className="bar-stack" role="img" aria-label={entries.map(x=>`${x.label} ${money(x.value)}`).join(", ")}>{entries.filter(x=>x.value>0).map(x=><div key={x.label} style={{width:`${pct(x.value,sum)}%`,background:x.color}} title={`${x.label} ${money(x.value)}`}/>)}</div><div className="legend">{entries.map(x=><div key={x.label}><i style={{background:x.color}}/>{x.label}<b>{money(x.value)}</b></div>)}</div></>;}
function FutureGraph({allocation,months,monthly}:{allocation:Allocation;months:number;monthly:number}){
  const sim=useMemo(()=>simulateFuture(allocation,months,monthly),[allocation,months,monthly]);
  const data=sim.rows.filter((x,i)=>i%Math.max(1,Math.floor(months/20))===0||i===months);
  const max=Math.max(1,...data.map(x=>x.optimistic));
  function points(key:"pessimistic"|"base"|"optimistic"|"contributed"){
    return data.map(x=>`${40+(x.month/months)*590},${210-(x[key]/max)*184}`).join(" ");
  }
  const end=sim.rows[sim.rows.length-1];
  return <div className="graph-wrap"><svg viewBox="0 0 670 252" role="img" aria-label={`미래 자산 추정치: 비관 ${end.pessimistic}만 원, 기본 ${end.base}만 원, 낙관 ${end.optimistic}만 원`}>
    {[0,0.25,0.5,0.75,1].map(n=><g key={n}><line x1="40" x2="630" y1={210-n*184} y2={210-n*184} stroke="#e6ebf3"/><text x="4" y={214-n*184} fontSize="12" fill="#8794a9">{Math.round(n*max/1000)}천</text></g>)}
    <polyline points={points("pessimistic")} stroke="#b4c4f7" strokeWidth="3" fill="none"/>
    <polyline points={points("optimistic")} stroke="#81c8ae" strokeWidth="3" fill="none"/>
    <polyline points={points("contributed")} stroke="#adb5c6" strokeWidth="2" strokeDasharray="5 7" fill="none"/>
    <polyline points={points("base")} stroke="#4265f5" strokeWidth="4" fill="none" strokeLinecap="round"/>
    {[0,months/3,months*2/3,months].map(n=><text key={n} x={40+(n/months)*590} y="244" textAnchor="middle" fontSize="12" fill="#8b96a8">{Math.round(n/12)}년</text>)}
  </svg><div className="line-legend"><span className="dot blue"/>기본 <span className="dot mint"/>낙관 <span className="dot pale"/>비관 <span className="dot gray"/>납입 원금</div><div className="forecast-row">{[["비관",end.pessimistic],["기본",end.base],["낙관",end.optimistic]].map(([k,v])=><div key={String(k)}><span className="muted">{k} 시나리오</span><strong>{money(Number(v))}</strong></div>)}</div></div>;
}
function Footer(){return <p className="disclaimer"><ShieldCheck size={15}/>{disclosure}</p>;}

export default function Moaplan(){
  const supabase=useMemo(()=>typeof window!=="undefined"&&process.env.NEXT_PUBLIC_SUPABASE_URL&&process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY?browserSupabase():null,[]);
  const [stage,setStage]=useState<Stage>("landing");const [tab,setTab]=useState<Tab>("home");
  const [user,setUser]=useState<any>(null);const [data,setData]=useState<State>(emptyState);const [busy,setBusy]=useState(false);const [error,setError]=useState("");const [notice,setNotice]=useState("");
  const [diag,setDiag]=useState({income:280,expense:165,assets:800});const [diagResult,setDiagResult]=useState<ReturnType<typeof freeDiagnose>|null>(null);
  const [authMode,setAuthMode]=useState({nickname:"",email:"",password:"",required:false,analytics:false});
  const [finance,setFinance]=useState(defaultFin);const [assets,setAssets]=useState(defaultAssets);
  const [answers,setAnswers]=useState<number[]>([]);const [questionIndex,setQuestionIndex]=useState(0);const [interests,setInterests]=useState<string[]>(["etf","overseas"]);
  const [goal,setGoal]=useState({type:"marriage",name:"결혼 자금",target_amount:3000,deadline:""});
  const [preview,setPreview]=useState<any>(null);const [showPurchase,setShowPurchase]=useState(false);const [showCancel,setShowCancel]=useState(false);const [cancelReason,setCancelReason]=useState("가격");
  const [selectedCard,setSelectedCard]=useState<typeof cards[number]|null>(null);const [showCards,setShowCards]=useState(false);
  const [futureMonths,setFutureMonths]=useState(120);const [monthly,setMonthly]=useState<number|null>(null);
  const [checkin,setCheckin]=useState({month:"",emergency:0,goal:0,safe:0,risky_overseas:0,risky_domestic:0,individual:0,coin:0,big_expense:0,note:""});
  const [checkinResult,setCheckinResult]=useState<any>(null);const [showCheckin,setShowCheckin]=useState(false);
  const [chatInput,setChatInput]=useState("");const [chatReply,setChatReply]=useState<any>(null);
  const [proposalType,setProposalType]=useState<"ratio"|"risk"|"coin"|"long_term_amount">("ratio");const [proposalValue,setProposalValue]=useState(80);const [proposal,setProposal]=useState<any>(null);
  const [scores,setScores]=useState({understanding:0,trust:0,value:0});const [feedback,setFeedback]=useState("");const [deleteConfirm,setDeleteConfirm]=useState("");
  const authRef=useRef("");
  const [newPassword,setNewPassword]=useState("");
  const active=data.blueprint?.allocation as Allocation|undefined;
  const isApp=stage==="app";
  function fillForms(s:State){
    if(s.profile)setFinance({nickname:s.profile.nickname||"",income:s.profile.income,income_type:s.profile.income_type,fixed_expense:s.profile.fixed_expense,living_expense:s.profile.living_expense,debt_payment:s.profile.debt_payment,analytics_consent:s.profile.analytics_consent});
    if(s.assets?.length)setAssets(Object.assign({...defaultAssets},Object.fromEntries(s.assets.map(x=>[x.kind,x.amount]))));
    if(s.risk){setAnswers(s.risk.answers??[]);setInterests(s.risk.interests??[]);}
    if(s.goal)setGoal({type:s.goal.type,name:s.goal.name,target_amount:s.goal.target_amount,deadline:s.goal.deadline});
    if(s.blueprint)setMonthly((s.blueprint.allocation as Allocation).longTerm);
  }
  function chooseStage(s:State){if(!s.profile)return "finance";if(!s.risk)return "risk";if(s.blueprint)return "app";return "goal";}
  async function reload(redirect=true){const s:State=await api("state");setData(s);fillForms(s);if(redirect)setStage(chooseStage(s));return s;}
  useEffect(()=>{
    if(!supabase)return;
    let mounted=true;
    const init=async()=>{const {data:{session}}=await supabase.auth.getSession();if(!mounted)return;
      if(session){setUser(session.user);try{await reload(!new URLSearchParams(window.location.search).has("reset"));if(new URLSearchParams(window.location.search).has("reset"))setStage("reset");}catch(e){setError(String(e));}} else {setUser(null);setStage("landing");}
    };
    void init();
    const {data:{subscription}}=supabase.auth.onAuthStateChange((evt,session)=>{
      if(!mounted)return;
      if(evt==="PASSWORD_RECOVERY"){setStage("reset");}
      else if(evt==="SIGNED_OUT"){setUser(null);setData(emptyState);setStage("landing");}
      else if(evt==="SIGNED_IN"&&session?.user&&authRef.current!==session.user.id){authRef.current=session.user.id;setUser(session.user);setTimeout(()=>{void reload(!new URLSearchParams(window.location.search).has("reset")).then(()=>{if(new URLSearchParams(window.location.search).has("reset"))setStage("reset");}).catch(e=>setError(String(e)));},0);}
    });
    return()=>{mounted=false;subscription.unsubscribe();};
  // eslint-disable-next-line react-hooks/exhaustive-deps
  },[supabase]);
  useEffect(()=>{const d=new Date();setCheckin(c=>({...c,month:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`}));
    const date=new Date(d.getFullYear()+3,d.getMonth(),d.getDate());setGoal(g=>({...g,deadline:`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`}));
    try{const x=window.sessionStorage.getItem("moaplan-diag");if(x){const j=JSON.parse(x);setDiag(j);setFinance(p=>({...p,income:j.income,fixed_expense:Math.max(0,Math.round(j.expense*.55)),living_expense:Math.max(0,j.expense-Math.round(j.expense*.55))}));setAssets(a=>({...a,deposit:j.assets}));}}catch{}
  },[]);
  async function run(action:()=>Promise<void>){setBusy(true);setError("");setNotice("");try{await action();}catch(e){setError(e instanceof Error?e.message:"오류가 발생했습니다.");}finally{setBusy(false);}}
  function navigate(tab:Tab){setTab(tab);setStage("app");setShowCards(false);setSelectedCard(null);window.scrollTo({top:0,behavior:"smooth"});}
  const onSignup=()=>run(async()=>{
    if(!supabase)throw Error("Supabase 환경 변수가 등록되지 않았습니다.");
    if(!authMode.required)throw Error("필수 약관 3개에 동의해 주세요.");
    if(authMode.password.length<8)throw Error("비밀번호는 8자 이상 입력해 주세요.");
    const {data:d,error:e}=await supabase.auth.signUp({email:authMode.email,password:authMode.password,options:{data:{nickname:authMode.nickname},emailRedirectTo:`${window.location.origin}/auth/callback`}});
    if(e)throw e;
    if(d.session){setUser(d.user);setFinance(p=>({...p,nickname:authMode.nickname,analytics_consent:authMode.analytics}));setStage("finance");}
    else setNotice("가입 요청이 접수되었습니다. 이메일 인증 링크를 확인한 다음 로그인해 주세요. (설정에 따라 인증 생략 가능)");
  });
  const onLogin=()=>run(async()=>{
    if(!supabase)throw Error("Supabase 환경 변수가 등록되지 않았습니다.");
    const {error:e}=await supabase.auth.signInWithPassword({email:authMode.email,password:authMode.password});if(e)throw Error(e.message);
    await reload(true);
  });
  const onKakao=()=>run(async()=>{if(!supabase)throw Error("Supabase 설정을 먼저 완료해 주세요.");
    const {error:e}=await supabase.auth.signInWithOAuth({provider:"kakao",options:{redirectTo:`${window.location.origin}/auth/callback`}});if(e)throw e;
  });
  const onReset=()=>run(async()=>{if(!supabase)throw Error("Supabase 설정이 없습니다.");if(!authMode.email)throw Error("이메일을 먼저 입력해 주세요.");
    const {error:e}=await supabase.auth.resetPasswordForEmail(authMode.email,{redirectTo:`${window.location.origin}/auth/callback?mode=recovery`});if(e)throw e;
    setNotice("비밀번호 재설정 메일을 확인해 주세요. 이메일의 링크를 통해 비밀번호 변경 화면으로 이동합니다.");
  });
  const onUpdatePassword=()=>run(async()=>{if(!supabase)throw Error("로그인 상태를 확인할 수 없습니다.");if(newPassword.length<8)throw Error("새 비밀번호는 8자 이상이어야 합니다.");const {error:e}=await supabase.auth.updateUser({password:newPassword});if(e)throw e;setNewPassword("");window.history.replaceState({},"","/");await reload(true);setNotice("비밀번호가 변경되었습니다.");});
  const onDiag=()=>run(async()=>{const r=await api("diagnose","POST",diag);setDiagResult(r);window.sessionStorage.setItem("moaplan-diag",JSON.stringify(diag));});
  const onFinance=()=>run(async()=>{
    await api("profile","PUT",finance);await api("assets","PUT",assets);setStage("risk");await reload(false);
  });
  const onRisk=()=>run(async()=>{await api("risk-profile","POST",{answers,interests});await reload(false);setStage("goal");});
  const onGoal= (none=false)=>run(async()=>{
    await api("goals","POST",none?{none:true}:goal);
    const p=await api("blueprints/preview","POST",{});setPreview(p);setStage("preview");await reload(false);
  });
  const onPurchase=()=>run(async()=>{
    if(!preview)throw Error("미리보기를 다시 열어 주세요.");
    await api("purchases","POST",{blueprint_id:preview.id,action:"complete",mockConfirmed:true});
    await reload(true);setTab("blueprint");setShowPurchase(false);
    setNotice("모의 결제가 완료되었습니다. 실제 금액은 청구되지 않았고 20포인트가 지급됐습니다.");
  });
  const onCancel=()=>run(async()=>{
    await api("purchases","POST",{blueprint_id:preview.id,action:"cancel",reason:cancelReason});setShowCancel(false);setShowPurchase(false);
    setNotice("결제 없이 미리보기로 돌아왔어요. 의견 감사합니다.");
  });
  const onCheckin=()=>run(async()=>{
    const r=await api("checkins","POST",checkin);setCheckinResult(r);await reload(false);
    setNotice(r.pointsGranted?"체크인이 저장되고 2포인트가 지급됐습니다.":"이번 달 체크인 기록을 수정했습니다. 포인트는 중복 지급되지 않아요.");
  });
  const onAsk=(question=chatInput)=>run(async()=>{
    const r=await api("ai/messages","POST",{question});setChatReply(r);setChatInput("");await reload(false);
  });
  const onProposal=()=>run(async()=>{const r=await api("proposals","POST",{request:{change_type:proposalType,value:proposalValue}});setProposal(r);});
  const onApply=()=>run(async()=>{if(!proposal?.allowed)throw Error("적용 가능한 변경안이 없습니다.");await api(`proposals/${proposal.id}/apply`,"POST",{});setProposal(null);await reload(false);setNotice("규칙 엔진이 다시 확인한 설계도 v2가 적용됐습니다. 3포인트 차감되었어요.");});
  const onDelete=()=>run(async()=>{
    if(deleteConfirm!=="삭제")throw Error("확인란에 '삭제'를 입력해 주세요.");
    if(!window.confirm("계정과 모든 재무정보가 영구적으로 삭제됩니다. 진행할까요?"))return;
    await api("me","DELETE",{});if(supabase)await supabase.auth.signOut();setUser(null);setData(emptyState);setStage("landing");setNotice("계정과 저장된 개인정보 삭제 요청이 완료되었습니다.");
  });
  const empty=<div className="empty"><div className="empty-icon"><LockKeyhole/></div><h3>설계도를 먼저 만들어 주세요</h3><p className="muted">무료 진단부터 시작하면 나만의 설계도로 이어집니다.</p><Btn onClick={()=>{setStage(user?"goal":"landing");}}>시작하기 <ArrowRight size={17}/></Btn></div>;
  const authenticated=!!user;
  return <div className="site-shell">
    {isApp&&<aside className="sidebar"><div className="sidebar-brand"><Brand/></div><div className="sidebar-nav">{(Object.keys(tabLabels) as Tab[]).map(k=>{const Icon=icons[k];return <button key={k} className={`nav-link ${tab===k?"active":""}`} onClick={()=>navigate(k)}><Icon size={20}/>{tabLabels[k]}{tab===k&&<ChevronRight size={16} className="nav-chev"/>}</button>;})}</div><div className="sidebar-bottom"><div className="avatar">{(data.profile?.nickname||user?.email||"M").slice(0,1).toUpperCase()}</div><div className="grow"><strong>{data.profile?.nickname||"모아플랜 사용자"}</strong><span className="muted tiny">{data.points}P · 모의 서비스</span></div></div></aside>}
    <main className={`main ${isApp?"app-main":""}`}>
      <header className="topbar"><Brand small/><div className="top-actions">{authenticated?<><span className="point-pill"><Sparkles size={14}/>{data.points} P</span><button className="plain small" onClick={()=>{void run(async()=>{await supabase?.auth.signOut();setUser(null);setStage("landing");});}}><LogOut size={17}/><span className="desktop-only">로그아웃</span></button></>:<><span className="test-badge">체험용 · 모의 결제</span><button className="plain small" onClick={()=>setStage("login")}>로그인</button></>}</div></header>
      {!supabase&&<div className="config-alert"><AlertCircle size={18}/>Supabase 환경 변수가 없습니다. `.env.local` 또는 Vercel 환경 변수를 설정해 주세요.</div>}
      {stage==="landing"&&<>
        <div className="hero"><div className="hero-content"><span className="hero-pill"><Sparkles size={14}/> 나에게 맞춘 자산 설계</span><h1>내 돈의 방향,<br/><span>모아플랜</span>에서 찾다.</h1><p>나의 소득과 자산, 투자 성향에 맞춰<br/>비상금부터 장기 투자까지 한눈에 설계해요.</p><div className="hero-points"><span><CheckCircle2 size={16}/>30초 무료 진단</span><span><CheckCircle2 size={16}/>3분 투자 성향 분석</span><span><CheckCircle2 size={16}/>계획 관리는 무료</span></div></div><div className="hero-visual"><div className="hero-floating"><span>이번 달 여유자금</span><strong>115 <small>만원</small></strong><div className="micro-bars"><i/><i/><i/><i/><i/><i/><i/><i/></div><small>내 자산을 나누는 첫걸음</small></div></div></div>
        <div className="landing-grid"><Block className="diagnose-card"><div className="card-heading"><span className="eyebrow">FREE CHECKUP</span><h2>10년 뒤, 내 자산은?</h2><p className="muted">가입 없이 숫자 3개만 입력해 보세요.</p></div><div className="three-fields"><Num label="세후 월 소득" value={diag.income} onChange={income=>setDiag({...diag,income})}/><Num label="한 달 총 지출" value={diag.expense} onChange={expense=>setDiag({...diag,expense})}/><Num label="지금 모아 둔 돈" value={diag.assets} onChange={assets=>setDiag({...diag,assets})}/></div><Btn className="wide" disabled={busy} onClick={onDiag}>무료로 계산하기 <ArrowRight size={18}/></Btn></Block>
        <Block className="diagnose-result"><div className="eyebrow">MY FINANCIAL SNAPSHOT</div>{diagResult?<><div className="result-number">{money(diagResult.surplus)}</div><span className="muted">한 달에 남는 여유자금</span><hr/><span className="muted">예금에만 넣을 경우 10년 뒤</span><h2 className="big-finance">{money(diagResult.future)}</h2>{diagResult.warning&&<p className="warn"><AlertCircle size={16}/>{diagResult.warning}</p>}<Cap>{diagResult.assumption}</Cap><Btn className="wide" onClick={()=>{setFinance(p=>({...p,income:diag.income,fixed_expense:diag.expense,living_expense:0}));setAssets(a=>({...a,deposit:diag.assets}));setStage("signup");}}>내 자산 설계도 만들기 <ArrowRight size={17}/></Btn></>:<><div className="preview-art"><div className="preview-art-title">월급을 어떻게 나누면 좋을까요?</div><div className="preview-art-bars"><i/><i/><i/><i/></div><div className="preview-art-mask"><LockKeyhole size={19}/> 무료 진단 결과를 먼저 확인해 보세요</div></div><p className="muted">계산 결과를 보고 가입하면 상세한 설계도로 이어져요.</p></>}</Block></div>
        <div className="feature-grid"><article><div className="feature-icon purple"><ClipboardList/></div><h3>나만의 자산 설계도</h3><p>비상금·목표 자금·장기 투자를 구분하는 월급 배분표</p></article><article><div className="feature-icon green"><BookOpen/></div><h3>쉬운 투자 공부</h3><p>상품 추천 없이 자산 종류와 위험을 이해하는 학습 카드</p></article><article><div className="feature-icon blue"><TrendingUp/></div><h3>무료 진행 관리</h3><p>10년 시뮬레이션·월별 체크인·계획과 실제 비교</p></article></div><Footer/>
      </>}
      {stage==="reset"&&<div className="auth-shell"><Block className="auth-card"><div className="auth-emblem"><LockKeyhole size={26}/></div><h1>새 비밀번호 설정</h1><p className="muted">이메일 인증을 마쳤다면 새 비밀번호를 입력하세요.</p><label className="field-wrap"><span className="field-label">새 비밀번호 (8자 이상)</span><input className="text-input" type="password" autoComplete="new-password" minLength={8} value={newPassword} onChange={e=>setNewPassword(e.target.value)}/></label><Btn className="wide" disabled={busy||newPassword.length<8} onClick={onUpdatePassword}>비밀번호 변경하기 <ArrowRight size={17}/></Btn></Block></div>}
      {(stage==="login"||stage==="signup")&&<div className="auth-shell"><Block className="auth-card"><div className="auth-emblem"><ShieldCheck size={26}/></div><h1>{stage==="login"?"다시 만나서 반가워요":"모아플랜 시작하기"}</h1><p className="muted">{stage==="login"?"내 자산 설계도를 계속 관리해요.":"가입하면 입력한 재무정보를 안전하게 저장해요."}</p>{stage==="signup"&&<label className="field-wrap"><span className="field-label">닉네임</span><input className="text-input" maxLength={30} placeholder="닉네임" value={authMode.nickname} onChange={e=>setAuthMode({...authMode,nickname:e.target.value})}/></label>}<label className="field-wrap"><span className="field-label">이메일</span><input type="email" className="text-input" placeholder="you@example.com" value={authMode.email} onChange={e=>setAuthMode({...authMode,email:e.target.value})}/></label><label className="field-wrap"><span className="field-label">비밀번호</span><input type="password" className="text-input" minLength={8} placeholder="8자 이상" value={authMode.password} onChange={e=>setAuthMode({...authMode,password:e.target.value})}/></label>
      {stage==="signup"&&<div className="consent-group"><label><input type="checkbox" checked={authMode.required} onChange={e=>setAuthMode({...authMode,required:e.target.checked})}/> <b>필수 동의</b> — 이용약관·개인 재무정보 처리·일반 정보 제공 및 투자 권유 아님</label><label><input type="checkbox" checked={authMode.analytics} onChange={e=>setAuthMode({...authMode,analytics:e.target.checked})}/> 선택 동의 — 사용 기록을 서비스 개선에 활용</label><Cap>실제 공개 서비스 운영 전 약관과 개인정보처리방침을 운영자 정보로 완성해야 합니다. 현재는 고객 테스트용 초안입니다.</Cap></div>}
      <Btn className="wide" disabled={busy} onClick={stage==="login"?onLogin:onSignup}>{stage==="login"?"로그인":"계정 만들기"} <ArrowRight size={18}/></Btn><div className="auth-divider">또는</div><Btn className="wide" outline onClick={onKakao}>카카오로 시작하기 <ArrowRight size={17}/></Btn><Cap>카카오 로그인은 Supabase와 Kakao Developers에 OAuth 제공자를 별도 설정해야 사용할 수 있습니다.</Cap><div className="auth-links"><button onClick={()=>setStage(stage==="login"?"signup":"login")}>{stage==="login"?"처음인가요? 회원가입":"이미 계정이 있나요? 로그인"}</button><button onClick={onReset}>비밀번호 재설정 메일</button></div></Block></div>}
      {stage==="finance"&&<div className="flow-page"><StepHead eyebrow="STEP 01 / 04 · 재무 정보" title="내 돈의 흐름을 알려주세요" subtitle="대략적인 숫자도 괜찮아요. 금액은 모두 만원 단위예요." progress={25}/><div className="two-panel"><Block><div className="card-heading"><h2>한 달 수입과 지출</h2><p className="muted">매달 얼마가 남는지 알아볼게요.</p></div><label className="field-wrap"><span className="field-label">닉네임</span><input className="text-input" value={finance.nickname} onChange={e=>setFinance({...finance,nickname:e.target.value})} maxLength={30} placeholder="어떻게 불러 드릴까요?"/></label><div className="segmented">{[["employee","직장인"],["self_employed","프리랜서·자영업"]].map(([value,text])=><button key={value} className={finance.income_type===value?"selected":""} onClick={()=>setFinance({...finance,income_type:value})}>{text}</button>)}</div><Num label="세후 월 소득" value={finance.income} onChange={income=>setFinance({...finance,income})}/><Num label="월 고정 지출" hint="월세·통신비·보험료 등" value={finance.fixed_expense} onChange={fixed_expense=>setFinance({...finance,fixed_expense})}/><Num label="월 변동 생활비" hint="식비·교통비·여가 등" value={finance.living_expense} onChange={living_expense=>setFinance({...finance,living_expense})}/><Num label="월 대출 상환액" value={finance.debt_payment} onChange={debt_payment=>setFinance({...finance,debt_payment})}/></Block><Block><div className="card-heading"><h2>지금 가진 자산</h2><p className="muted">상품·종목명 없이 자산 종류별 합계만 입력해요.</p></div><div className="asset-grid">{assetKinds.map(([key,name])=><Num key={key} label={name} value={assets[key]} onChange={v=>setAssets({...assets,[key]:v})}/>)}</div><div className="calculation-box"><span>현재 자산 합계</span><b>{money(Object.values(assets).reduce((s,v)=>s+v,0))}</b></div><div className="calculation-box light"><span>한 달 여유자금</span><b>{money(Math.max(0,finance.income-finance.fixed_expense-finance.living_expense-finance.debt_payment))}</b></div><Cap>잘 모르겠다면 고정 지출은 소득의 35%, 생활비는 25%를 출발점으로 삼을 수 있습니다. 실제 지출에 맞춰 수정하세요.</Cap><Btn outline className="wide" onClick={()=>setFinance(p=>({...p,fixed_expense:Math.round(p.income*.35),living_expense:Math.round(p.income*.25)}))}>기준값으로 채우기</Btn></Block></div><div className="flow-footer"><Btn disabled={busy||finance.income<=0} onClick={onFinance}>다음 · 투자 성향 알아보기 <ArrowRight size={18}/></Btn></div></div>}
      {stage==="risk"&&<div className="flow-page narrow"><StepHead eyebrow="STEP 02 / 04 · 투자 성향" title="나는 어떤 투자 유형일까요?" subtitle="정답은 없어요. 내 성향에 맞게 5문항을 선택해 주세요." progress={45}/><Block className="risk-card">{answers.length===5&&questionIndex>=5?<><div className="result-bubble"><Sparkles size={24}/></div><span className="eyebrow">MY INVESTMENT TYPE</span><h2>당신은 {riskFromAnswers(answers,interests).type}</h2><div className="big-finance">{riskFromAnswers(answers,interests).score}점 <small>/100점</small></div><p className="muted">안전과 위험의 균형을 내 투자 기간에 맞게 찾아가요.</p><h3>관심 있는 자산</h3><div className="chip-row">{[["overseas","해외 주식"],["etf","ETF"],["domestic","국내 주식"],["coin","가상자산"]].map(([key,name])=><button className={`chip ${interests.includes(key)?"selected":""}`} key={key} onClick={()=>setInterests(a=>a.includes(key)?a.filter(x=>x!==key):[...a,key])}>{name}</button>)}</div><Cap>관심 자산은 공부 카드 구성에 활용합니다. 실제 자산 배분은 별도 위험 한도를 적용합니다.</Cap><Btn className="wide" disabled={busy} onClick={onRisk}>결과 저장하고 계속하기 <ArrowRight size={18}/></Btn></>:<><div className="risk-progress"><span>질문 {questionIndex+1} / 5</span><span>차근차근 알아가요</span></div><h2>{riskQuestions[questionIndex].q}</h2><div className="answer-list">{riskQuestions[questionIndex].choices.map((answer,i)=><button key={answer} className="answer-button" onClick={()=>{const copy=[...answers];copy[questionIndex]=(i+1)*5;setAnswers(copy);setQuestionIndex(questionIndex+1);}}><span className="answer-number">{i+1}</span>{answer}<ChevronRight size={17}/></button>)}</div><button className="text-action" onClick={()=>{if(questionIndex>0)setQuestionIndex(questionIndex-1);}} disabled={questionIndex===0}><ArrowLeft size={15}/> 이전 질문</button></>}</Block></div>}
      {stage==="goal"&&<div className="flow-page narrow"><StepHead eyebrow="STEP 03 / 04 · 목표 설정" title="지금 이루고 싶은 목표가 있나요?" subtitle="목표가 없으면 전액을 장기 자산으로 설계할게요." progress={70}/><Block><div className="chip-row choice-grid">{[["marriage","결혼 자금"],["housing","전세·내 집"],["custom","직접 입력"]].map(([key,label])=><button key={key} className={`choice-tile ${goal.type===key?"selected":""}`} onClick={()=>setGoal({...goal,type:key,name:label})}><Target size={20}/>{label}</button>)}</div><label className="field-wrap"><span className="field-label">목표 이름</span><input className="text-input" maxLength={60} value={goal.name} onChange={e=>setGoal({...goal,name:e.target.value})}/></label><Num label="목표 금액" value={goal.target_amount} onChange={target_amount=>setGoal({...goal,target_amount})}/><label className="field-wrap"><span className="field-label">언제까지 모을까요?</span><input className="text-input" type="date" value={goal.deadline} onChange={e=>setGoal({...goal,deadline:e.target.value})}/></label><div className="tip"><Info size={18}/><span>3년 이내 사용할 돈은 위험자산으로 배분하지 않는 원칙을 적용해요.</span></div><Btn className="wide" disabled={busy} onClick={()=>onGoal(false)}>설계도 미리보기 <ArrowRight size={18}/></Btn><Btn className="wide" outline disabled={busy} onClick={()=>onGoal(true)}>목표 없이 장기 투자만 설계하기</Btn></Block></div>}
      {stage==="preview"&&<div className="flow-page narrow"><StepHead eyebrow="STEP 04 / 04 · 설계도 미리보기" title="내 돈의 방향을 준비했어요" subtitle="일부만 먼저 보여드릴게요. 모의 구매 후 전체 설계도를 확인할 수 있어요." progress={92}/><Block className="preview-card"><div className="preview-top"><span className="eyebrow">MOAPLAN BLUEPRINT · PREVIEW</span><span className="status-tag"><LockKeyhole size={13}/> 미리보기</span></div><div className="preview-hero"><span>매달 여유자금</span><strong>{preview?money(preview.surplus):"계산 중"}</strong></div><div className="preview-row"><span>비상금 기준</span><strong>{money(preview?.emergencyTarget||0)}</strong></div><div className="preview-row"><span>비상금 확보</span><strong>{(preview?.emergencyHeld??0)>=(preview?.emergencyTarget??1)?"충족":"적립 필요"}</strong></div><div className="preview-row"><span>투자 성향</span><strong>{preview?.riskType||"진단 완료"}</strong></div><div className="locked-section"><div className="blur-bars"><div><span>목표 자금</span><strong>••• 만 원</strong></div><div><span>장기 투자</span><strong>••• 만 원</strong></div><div><span>안전·위험 자산 비중</span><strong>••• / •••</strong></div></div><div className="lock-overlay"><LockKeyhole/><b>전체 배분표는 구매 후 공개돼요</b></div></div><div className="price-box"><div><span>1회 자산 설계도</span><strong>1,000원</strong></div><div className="bonus"><Sparkles size={18}/> AI 질문 20포인트 포함</div></div><p className="mock-note"><ShieldCheck size={17}/> 지금은 고객 테스트용 모의 결제입니다. 실제 금액이 청구되지 않습니다.</p><Btn className="wide" onClick={()=>setShowPurchase(true)}>1,000원으로 전체 설계도 받기 <ArrowRight size={18}/></Btn><button className="text-action centered" onClick={()=>setShowCancel(true)}>다음에 할게요</button></Block></div>}
      {isApp&&<div className="dashboard">
        {tab==="home"&&(active?<><div className="dash-title"><div><span className="eyebrow">DASHBOARD</span><h1>안녕하세요, {data.profile?.nickname||"모아플랜"}님 👋</h1><p className="muted">오늘도 내 자산의 방향을 확인해 볼까요?</p></div><span className="badge-soft"><CheckCircle2 size={16}/> 설계도 v{data.blueprint?.version}</span></div>
          <div className="stat-grid"><Block className="stat dark"><Wallet size={22}/><span>현재 입력 자산</span><strong>{money(field(active.totalAssets)+(data.checkins??[]).reduce((n,x)=>n+x.safe+x.goal+x.emergency+x.risky_overseas+x.risky_domestic+x.individual+x.coin,0))}</strong><small>입력 자산 + 체크인 저축 누적 · 시세 변동 미반영</small></Block><Block className="stat"><Target size={22}/><span>월 여유자금</span><strong>{money(active.surplus)}</strong><small>수입 − 지출 − 월 상환액</small></Block><Block className="stat"><Sparkles size={22}/><span>사용 가능한 포인트</span><strong>{data.points} <small>P</small></strong><small>체크인으로 매월 +2P</small></Block></div>
          <div className="content-grid"><Block><div className="card-heading row"><div><h2>내 자산의 배분</h2><p className="muted">장기 투자 예상 월 배분표</p></div><button className="link" onClick={()=>navigate("blueprint")}>설계도 상세 <ArrowRight size={16}/></button></div><Bar entries={[{label:"안전자산",value:active.safe,color:"#8cb3fa"},{label:"해외 지수형",value:active.overseas,color:"#4566f1"},{label:"국내 지수형",value:active.domestic,color:"#6c88ef"},{label:"개별 주식",value:active.individual,color:"#a99af8"},{label:"가상자산",value:active.coin,color:"#d3a0ed"}]}/>{active.warnings.length>0&&<div className="warning-list">{active.warnings.map((w:string)=><p key={w}><AlertCircle size={17}/>{w}</p>)}</div>}</Block><Block><div className="card-heading row"><div><h2>진행 상황</h2><p className="muted">매달 기록하면서 채워가요.</p></div><span className="status-tag">{data.checkins.length}개월 기록</span></div><div className="progress-box"><Ring value={active.goalTarget?pct(active.goalExisting+data.checkins.reduce((s,x)=>s+x.goal,0),active.goalTarget):pct(active.emergencyHeld+data.checkins.reduce((s,x)=>s+x.emergency,0),active.emergencyTarget)} label={active.goalTarget?"목표 달성률":"비상금 달성률"}/><div><span className="muted">{active.goalTarget?"목표 자금":"비상금"}</span><h3>{active.goalTarget?money(active.goalTarget):money(active.emergencyTarget)}</h3><p className="muted">이번 달의 실적을 추가해 주세요.</p><Btn outline onClick={()=>setShowCheckin(true)}>월간 체크인 <ArrowRight size={16}/></Btn></div></div></Block></div>
          {data.checkins.length>0&&(()=>{const latest=data.checkins[0];const actualRisk=latest.risky_overseas+latest.risky_domestic+latest.individual+latest.coin;const actualSafe=latest.safe;const actualPct=pct(actualRisk,actualRisk+actualSafe);const difference=Math.abs(actualPct-active.riskPct);return <Block className={difference>=10?"deviation":""}><h2>설계와 실제 비중 비교</h2><div className="compare-row"><span>설계상 위험자산</span><strong>{active.riskPct}%</strong></div><div className="compare-row"><span>최근 체크인 위험자산</span><strong>{actualPct}%</strong></div>{difference>=10&&<p className="warn"><AlertCircle size={17}/>최근 비중이 설계와 {difference}%p 차이 나요. 조정을 검토해 보세요.</p>}</Block>})()}
          {data.checkins.length===0&&<Block className="notice-card"><CalendarCheck size={24}/><div><h3>첫 월간 체크인을 시작해요</h3><p className="muted">실제 저축 금액을 기록하면 자산 진행률이 업데이트되고 2P를 받을 수 있어요.</p></div><Btn onClick={()=>setShowCheckin(true)}>시작하기</Btn></Block>}
          <div className="quick-links"><button onClick={()=>navigate("blueprint")}><ClipboardList/>설계도 보기<ChevronRight/></button><button onClick={()=>navigate("future")}><TrendingUp/>10년 뒤 자산<ChevronRight/></button><button onClick={()=>navigate("coach")}><MessageCircle/>AI 질문하기<ChevronRight/></button></div>
        </>:empty)}
        {tab==="blueprint"&&(active?<><div className="dash-title"><div><span className="eyebrow">MY BLUEPRINT · VERSION {data.blueprint?.version}</span><h1>나만의 자산 설계도</h1><p className="muted">소득·지출·자산·성향에 따라 만든 월별 배분 가이드예요.</p></div><span className="badge-soft"><CheckCircle2 size={16}/> 활성 설계도</span></div>
          <div className="blueprint-summary"><div><span>매달 여유자금</span><strong>{money(active.surplus)}</strong></div><div><span>비상금 목표</span><strong>{money(active.emergencyTarget)}</strong></div><div><span>장기 투자 월액</span><strong>{money(active.longTerm)}</strong></div></div>
          <div className="content-grid"><Block><div className="card-heading"><span className="eyebrow">01 · MONTHLY ALLOCATION</span><h2>월급 배분표</h2></div><div className="bucket-row"><div className="bucket-icon mint"><ShieldCheck/></div><div><strong>비상금 적립</strong><p className="muted">6개월 기준 부족분 채우기</p></div><b>{money(active.emergencyMonthly)}</b></div><div className="bucket-row"><div className="bucket-icon blue"><Target/></div><div><strong>목표 자금</strong><p className="muted">원금 보전 우선</p></div><b>{money(active.goalMonthly)}</b></div><div className="bucket-row"><div className="bucket-icon purple"><TrendingUp/></div><div><strong>장기 투자</strong><p className="muted">성향별 위험 비중 적용</p></div><b>{money(active.longTerm)}</b></div><div className="calculation-box"><span>월 여유자금 합계</span><b>{money(active.emergencyMonthly+active.goalMonthly+active.longTerm)}</b></div></Block><Block><div className="card-heading"><span className="eyebrow">02 · ASSET MIX</span><h2>장기 자산 비중</h2><p className="muted">안전자산 {pct(active.safe,active.longTerm)}% · 위험자산 {pct(active.risky,active.longTerm)}%</p></div><Bar entries={[{label:"안전자산",value:active.safe,color:"#a0bdf8"},{label:"해외 지수형",value:active.overseas,color:"#4566f1"},{label:"국내 지수형",value:active.domestic,color:"#718ef0"},{label:"개별 주식",value:active.individual,color:"#a99af8"},{label:"가상자산",value:active.coin,color:"#d3a0ed"}]}/><Cap>지수형 자산은 위험자산의 70% 이상을 기본으로 유지합니다.</Cap></Block></div>
          <Block><div className="card-heading"><span className="eyebrow">03 · ACTION STEPS</span><h2>이 순서로 관리해 보세요</h2></div><div className="steps-list">{active.steps.map((s:string,i:number)=><div key={s}><span className={`step-count ${i===0?"complete":""}`}>{i===0?<Check size={17}/>:i+1}</span><div><b>{s}</b><Cap>{i===0?"갑작스러운 지출을 대비해요.":"목표를 우선하고 남는 돈을 장기로 나눠요."}</Cap></div></div>)}</div>{active.alternatives.length>0&&<div className="warning-list">{active.alternatives.map((a:string)=><p key={a}><Info size={16}/>{a}</p>)}</div>}</Block>
          <Block><div className="card-heading"><span className="eyebrow">04 · EXPLANATION</span><h2>왜 이렇게 나눴나요?</h2></div><div className="explain-text">비상금은 필요한 생활비를 기준으로 준비하고, 기한이 있는 목표에 먼저 자금을 배분했어요. 그 다음 남는 여유자금을 투자 성향과 장기 기간에 맞게 안전자산·위험자산으로 나눴어요.</div><details className="details"><summary>계산 근거 펼치기 <ChevronDown size={16}/></summary><p>월 여유자금 = 월 소득 − 고정 지출 − 생활비 − 대출 상환액</p><p>비상금 = (고정 지출 + 생활비) × 직장인 3개월 / 프리랜서 6개월</p><p>목표 저축 = 부족한 목표금액 ÷ 남은 개월(올림). 여유자금 이내까지만 배분합니다.</p><p>규칙 버전: {data.blueprint?.rules_version}</p></details></Block>
          <div className="section-inline"><div><h2>내 설계도, 더 자세히 알아보기</h2><p className="muted">내 설계도에 연결된 투자 공부 카드</p></div><Btn outline onClick={()=>setShowCards(!showCards)}><BookOpen size={17}/> {showCards?"카드 닫기":"공부 카드 보기"}</Btn></div>
          {showCards&&<div className="cards-grid">{cards.filter(c=>["deposit","dca","diversification","cost"].includes(c.id)||(c.id==="foreign"&&active.overseas>0)||(c.id==="domestic"&&active.domestic>0)||(c.id==="coin"&&active.coin>0)||(c.id==="stocks"&&active.individual>0)).map(c=><button key={c.id} className="study-card" onClick={()=>{setSelectedCard(c);void api("events","POST",{name:"card_viewed"}).catch(()=>{});}}><div className="study-icon"><BookOpen size={20}/></div><span className="eyebrow">{c.type}</span><strong>{c.title}</strong><p>{c.summary}</p><span className="link">자세히 읽기 <ArrowRight size={15}/></span></button>)}</div>}
          <Block><div className="card-heading"><h2>자산 설계도는 도움이 되었나요?</h2><p className="muted">3가지 항목에 1~5점으로 응답해 주세요.</p></div>{[["understanding","설계도를 이해하기 쉬웠나요?"],["trust","계산 근거를 신뢰하나요?"],["value","실제로 1,000원 가치가 있다고 생각하나요?"]].map(([k,title])=><div key={k} className="survey-row"><span>{title}</span><div>{[1,2,3,4,5].map(v=><button key={v} className={`score ${scores[k as keyof typeof scores]===v?"selected":""}`} onClick={()=>setScores({...scores,[k]:v})}>{v}</button>)}</div></div>)}<Btn outline disabled={busy||Object.values(scores).some(v=>v===0)} onClick={()=>void run(async()=>{for(const [k,score] of Object.entries(scores))await api("surveys","POST",{question:k,score});setNotice("소중한 평가를 저장했습니다.");})}>평가 제출</Btn></Block><Footer/>
        </>:empty)}
        {tab==="future"&&(active?<><div className="dash-title"><div><span className="eyebrow">FUTURE SIMULATOR</span><h1>10년 뒤 내 자산은?</h1><p className="muted">장기 투자금만으로 계산한 세 가지 가상 시나리오예요.</p></div></div><Block className="forecast-card"><div className="card-heading row"><div><h2>장기 투자 성장 추정</h2><p className="muted">장기 투자 월 납입액 기준</p></div><div className="segmented small">{[36,60,120].map(x=><button key={x} className={futureMonths===x?"selected":""} onClick={()=>setFutureMonths(x)}>{x/12}년</button>)}</div></div><FutureGraph allocation={active} months={futureMonths} monthly={monthly??active.longTerm}/><div className="slide-control"><div className="row"><b>월 장기 투자금</b><strong>{money(monthly??active.longTerm)}</strong></div><input type="range" min={0} max={Math.max(100,active.longTerm*2)} step={5} value={monthly??active.longTerm} onChange={e=>setMonthly(Number(e.target.value))}/><div className="row muted tiny"><span>0만 원</span><span>{money(Math.max(100,active.longTerm*2))}</span></div></div>{(monthly??active.longTerm)>active.longTerm&&<p className="warn"><AlertCircle size={16}/>현재 장기 투자 배분을 초과해요. 목표·비상금에서 빼지 않는 한 적용할 수 없어요.</p>}<Cap>현재 보유 자산과 목표자금은 제외한 장기 투자 적립분의 예상 결과입니다. 세금·수수료·물가 미반영, 연 수익률은 단순 가정이며 보장되지 않습니다.</Cap><Btn outline onClick={()=>{setProposalType("long_term_amount");setProposalValue(monthly??active.longTerm);navigate("coach");setNotice("AI 질문 화면의 조정 제안에서 금액을 확인해 주세요.");}}>이 금액으로 조정 검토하기 <ArrowRight size={16}/></Btn></Block><Footer/></>:empty)}
        {tab==="coach"&&(active?<><div className="dash-title"><div><span className="eyebrow">FINANCIAL LEARNING ASSISTANT</span><h1>궁금한 걸 물어보세요</h1><p className="muted">자산 유형을 쉬운 말로 설명하고, 설계도 변경은 규칙 엔진이 검증해요.</p></div><span className="point-pill"><Sparkles size={16}/>{data.points} P</span></div><div className="content-grid"><Block className="chat-card"><div className="chat-top"><div className="chat-bot"><BrainCircuit size={22}/></div><div><strong>모아플랜 코치</strong><p className="muted tiny">실제 AI 연결 시 1문항 1P · 미연결 시 무료 기본 안내</p></div></div><div className="chat-stream"><div className="bubble assistant">안녕하세요! 저는 자산 배분 원칙을 설명해 드려요. 상품·종목을 추천하거나 수익을 보장하지는 않아요.</div>{data.messages.slice(-15).map((m:any)=><div key={m.id} className={`bubble ${m.role==="user"?"mine":"assistant"}`}><span>{m.content}</span>{m.role==="assistant"&&<button className="tiny muted report-btn" onClick={()=>void run(async()=>{await api("ai/report","POST",{id:m.id});setNotice("답변 신고가 기록됐습니다.");})}>{m.flagged?"신고됨":"답변 신고"}</button>}</div>)}{chatReply&&!chatReply.ai&&<div className="non-ai-notice">마지막 답변은 외부 AI 대신 규칙 기반 기본 안내로 제공됐습니다.</div>}</div><div className="quick-questions">{["비상금은 왜 따로 모으나요?","해외 비중을 늘리고 싶어요","장기 투자는 어떻게 나눠요?"].map(q=><button key={q} onClick={()=>onAsk(q)} disabled={busy}>{q}</button>)}</div><div className="chat-input"><input aria-label="질문 입력" placeholder="자산 종류나 배분 원칙을 질문해 보세요" maxLength={400} value={chatInput} onChange={e=>setChatInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&chatInput.trim().length>=2)onAsk();}}/><button onClick={()=>onAsk()} disabled={busy||chatInput.trim().length<2} aria-label="질문 전송"><Send size={18}/></button></div><Cap>질문에 이름·이메일 등 식별정보를 넣지 마세요. 외부 AI는 API 키를 설정한 경우에만 사용됩니다.</Cap></Block>
          <Block className="adjust-card"><div className="card-heading"><span className="eyebrow">ASSET ADJUSTMENT</span><h2>설계도 변경안 비교</h2><p className="muted">성향 상한을 넘지 않는지 먼저 검증합니다. 적용 시 3P 사용.</p></div><label className="field-wrap"><span className="field-label">어떤 부분을 바꾸고 싶나요?</span><select className="text-input" value={proposalType} onChange={e=>{setProposalType(e.target.value as typeof proposalType);setProposal(null);}}><option value="ratio">위험자산 내 해외 비중 (%)</option><option value="risk">장기 투자 내 위험자산 비중 (%)</option><option value="coin">위험자산 내 가상자산 비중 (%)</option><option value="long_term_amount">장기 투자 월 금액 (만원)</option></select></label><Num label={proposalType==="long_term_amount"?"월 장기 투자 금액":"변경할 비중"} value={proposalValue} onChange={setProposalValue} max={proposalType==="long_term_amount"?100000:100}/><Btn className="wide" outline disabled={busy} onClick={onProposal}><SlidersHorizontal size={17}/> 변경 전후 비교하기</Btn>{proposal&&<div className="proposal-result">{proposal.allowed?<><p className="good"><CheckCircle2 size={18}/>규칙 엔진 검증 통과</p><div className="compare-row"><span>변경 전 장기 투자</span><strong>{money(proposal.before?.longTerm??active.longTerm)}</strong></div><div className="compare-row"><span>변경 후 장기 투자</span><strong>{money(proposal.after.longTerm)}</strong></div><div className="compare-row"><span>안전 / 위험</span><strong>{money(proposal.after.safe)} / {money(proposal.after.risky)}</strong></div><div className="compare-row"><span>해외 지수형 / 국내 지수형</span><strong>{money(proposal.after.overseas)} / {money(proposal.after.domestic)}</strong></div><Btn className="wide" disabled={busy||data.points<3} onClick={onApply}>3포인트로 조정 적용 <ArrowRight size={16}/></Btn></>:<p className="warn"><ShieldAlert size={17}/>{proposal.reason}</p>}</div>}{data.points<3&&<><p className="warn"><AlertCircle size={16}/>포인트가 부족해요. 체크인으로 2P를 받을 수 있어요.</p><Btn outline onClick={()=>void run(async()=>{const d=await api("points/charge-intent","POST",{});setNotice(d.message);})}>포인트 충전하기 (준비 중)</Btn></>}</Block></div><Footer/></>:empty)}
        {tab==="settings"&&<><div className="dash-title"><div><span className="eyebrow">MY SETTINGS</span><h1>내 정보 관리</h1><p className="muted">재무정보, 성향, 의견, 계정 삭제를 관리해요.</p></div></div><div className="content-grid"><Block><div className="card-heading"><h2>내 정보</h2></div><div className="preview-row"><span>이메일</span><strong>{user?.email||"연결된 계정"}</strong></div><div className="preview-row"><span>닉네임</span><strong>{data.profile?.nickname||"미설정"}</strong></div><div className="preview-row"><span>투자 성향</span><strong>{data.risk?.type||"미검사"}</strong></div><Btn outline className="wide" onClick={()=>setStage("finance")}><RefreshCcw size={16}/> 재무 정보 수정</Btn><Btn outline className="wide" onClick={()=>{setQuestionIndex(0);setAnswers([]);setStage("risk");}}><BrainCircuit size={16}/> 투자 성향 재진단</Btn><Cap>재무정보 또는 성향을 수정해도 이미 구매한 설계도는 자동으로 재발급되지 않습니다. 기존 설계도에는 당시 입력값과 규칙 버전이 보존됩니다.</Cap></Block><Block><div className="card-heading"><h2>의견 보내기</h2><p className="muted">사용하면서 불편했던 점을 알려주세요.</p></div><textarea className="textarea" value={feedback} maxLength={1500} onChange={e=>setFeedback(e.target.value)} placeholder="이해하기 어려운 설명, 사용 중 오류 등"/><Btn outline disabled={busy||feedback.trim().length<5} onClick={()=>void run(async()=>{await api("feedback","POST",{content:feedback});setFeedback("");setNotice("의견이 저장되었습니다.");})}>의견 전송하기 <Send size={16}/></Btn></Block></div><Block className="danger-zone"><h2>내 데이터 전체 삭제</h2><p className="muted">계정을 삭제하면 내 모든 재무정보·설계도·포인트·체크인 기록이 영구 삭제됩니다. 이벤트는 익명화됩니다.</p><label className="field-wrap"><span className="field-label">확인하려면 '삭제' 입력</span><input className="text-input" value={deleteConfirm} onChange={e=>setDeleteConfirm(e.target.value)} placeholder="삭제"/></label><Btn outline disabled={busy||deleteConfirm!=="삭제"} onClick={onDelete}><Trash2 size={17}/> 계정 및 모든 데이터 삭제</Btn></Block><Footer/></>}
      </div>}
    </main>
    {isApp&&<nav className="bottom-nav" aria-label="주요 메뉴">{(Object.keys(tabLabels) as Tab[]).map(k=>{const Icon=icons[k];return <button key={k} className={tab===k?"active":""} onClick={()=>navigate(k)}><Icon size={21}/><span>{tabLabels[k]}</span></button>;})}</nav>}
    {showPurchase&&<div className="modal-shade"><div className="modal"><button className="close" onClick={()=>setShowPurchase(false)} aria-label="닫기"><X/></button><div className="modal-icon"><CreditCard size={30}/></div><h2>모의 결제 확인</h2><p>내 자산 설계도를 <b>1,000원</b>에 구매하는 흐름을 체험합니다.</p><div className="payment-summary"><span>설계도 체험 가격</span><strong>1,000원</strong></div><div className="payment-summary"><span>구매 후 지급</span><strong>+20 P</strong></div><p className="mock-note"><ShieldCheck size={18}/> 실제 결제·카드번호 입력·금액 청구는 절대 발생하지 않습니다.</p><Btn className="wide" disabled={busy} onClick={onPurchase}>모의 구매 완료하기 <ArrowRight size={17}/></Btn><button className="text-action centered" onClick={()=>{setShowPurchase(false);setShowCancel(true);}}>구매하지 않기</button></div></div>}
    {showCancel&&<div className="modal-shade"><div className="modal"><button className="close" onClick={()=>setShowCancel(false)} aria-label="닫기"><X/></button><h2>다음에 다시 볼게요</h2><p>어떤 점이 망설여지셨나요?</p><div className="answer-list">{["가격","필요 없음","믿기 어려움","기타"].map(v=><button key={v} className={`answer-button ${cancelReason===v?"selected":""}`} onClick={()=>setCancelReason(v)}>{v}{cancelReason===v&&<Check size={17}/>}</button>)}</div><Btn className="wide" onClick={onCancel}>의견 남기고 미리보기로</Btn></div></div>}
    {selectedCard&&<div className="modal-shade"><div className="modal study-modal"><button className="close" aria-label="닫기" onClick={()=>setSelectedCard(null)}><X/></button><span className="eyebrow">{selectedCard.type} · INVESTMENT BASICS</span><h2>{selectedCard.title}</h2><h3>이런 자산이에요</h3><p>{selectedCard.summary}</p><h3>주의할 위험</h3><p>{selectedCard.risk}</p><div className="source-box">출처: <a href={selectedCard.url} target="_blank" rel="noreferrer">{selectedCard.source}</a><p className="muted tiny">외부 기관의 일반 안내 자료이며, 장래 수익을 보장하지 않습니다.</p></div><Btn className="wide" onClick={()=>{setSelectedCard(null);navigate("coach");}}>코치에게 더 물어보기 <ArrowRight size={16}/></Btn></div></div>}
    {showCheckin&&active&&<div className="modal-shade"><div className="modal checkin-modal"><button className="close" aria-label="닫기" onClick={()=>{setShowCheckin(false);setCheckinResult(null);}}><X/></button><span className="eyebrow">MONTHLY CHECK-IN</span><h2>이번 달 얼마나 모았나요?</h2><Cap>금액은 만원 단위입니다. 같은 달에는 수정만 가능하며 추가 포인트는 지급되지 않아요.</Cap><label className="field-wrap"><span className="field-label">기록할 월</span><input className="text-input" type="month" value={checkin.month} onChange={e=>setCheckin({...checkin,month:e.target.value})}/></label><div className="check-grid">{([["emergency","비상금"],["goal","목표 자금"],["safe","장기 안전자산"],["risky_overseas","해외 지수형"],["risky_domestic","국내 지수형"],["individual","개별 주식"],["coin","가상자산"],["big_expense","큰 지출"]] as [keyof typeof checkin,string][]).map(([k,n])=><Num key={k} label={n} value={Number(checkin[k])||0} onChange={v=>setCheckin({...checkin,[k]:v})}/>)}</div><label className="field-wrap"><span className="field-label">한 줄 메모 (선택)</span><input className="text-input" value={checkin.note} onChange={e=>setCheckin({...checkin,note:e.target.value})} maxLength={300} placeholder="이번 달 한 가지 기록"/></label><Btn className="wide" disabled={busy} onClick={onCheckin}>체크인 저장하기 <ArrowRight size={16}/></Btn>{checkinResult&&<div className="proposal-result"><h3>다음 달 재조정 예시</h3><p className="muted">아래 결과는 참고용이며 설계도 자체를 자동 변경하지는 않습니다.</p>{checkinResult.adjustment?.choices?.map((c:any)=><div className="compare-row" key={c.name}><span>{c.name}</span><strong>목표 월 {money(c.goalMonthly)}</strong></div>)}</div>}</div></div>}
    {(error||notice)&&<Toast message={error||notice} onDismiss={()=>{setError("");setNotice("");}}/>}
    {busy&&<div className="busy-bar" role="status" aria-label="처리 중"/>}
  </div>;
}
